/// policy. This is concrete native-session authority and Manga-only; callers
/// cannot use it to lower the separate signed or user/group social gates.
pub(crate) async fn mutate_native_manga_in(
    tx: &Transaction<'_>,
    actor: &crate::domains::auth::SessionPrincipal,
