async fn mutate_with_policy_in(
    tx: &Transaction<'_>,
    actor: &impl CatalogMutationActor,
    target: Target,
    id: &str,
    follow: bool,
    version: Option<i32>,
    expected_account: Option<&str>,
    require_verified: bool,
) -> ApiResult<Value> {
    if version.is_some_and(|v| v < 0) {
        return Err(ApiError::bad_request("Follow version must be nonnegative"));
    }
    actor.require_permission("self.preferences.update")?;
    let user=tx.query_opt("SELECT verified,disabled,roles,permissions FROM platform.users WHERE id=$1 FOR NO KEY UPDATE",&[&actor.user_id()]).await?.ok_or_else(ApiError::unauthorized)?;
    let roles: Vec<String> =
        serde_json::from_value(user.get(2)).map_err(|_| ApiError::unavailable())?;
    let permissions: Vec<String> =
        serde_json::from_value(user.get(3)).map_err(|_| ApiError::unavailable())?;
