        || user.get::<_, bool>(1)
        || roles
            .iter()
            .any(|r| matches!(r.as_str(), "banned" | "restricted"))
        || !permissions.iter().any(|p| p == "self.preferences.update")
    {
        return Err(ApiError::forbidden("This account cannot change follows"));
    }
    let account_id = super::account_public_id_in(tx, actor.user_id()).await?;
    if expected_account.is_some_and(|id| id != account_id) {
        return Err(ApiError::conflict(
            "Account binding changed; refresh before submitting",
        ));
    }
    if matches!(target, Target::User) && id == actor.user_id() {
        return Err(ApiError::bad_request("An account cannot follow itself"));
    }
