        let sql = match target {
            Target::Manga => {
                "SELECT id FROM platform.catalog_manga WHERE id=$1 AND deleted_at IS NULL AND state='published' AND protocol_source_visible AND platform.protocol_source_is_visible(protocol_series_id) FOR NO KEY UPDATE"
            }
            Target::Group => {
                "SELECT id FROM platform.catalog_groups WHERE id=$1 AND deleted_at IS NULL AND platform.protocol_group_is_visible(id) FOR SHARE"
            }
            Target::User => {
                "SELECT id FROM platform.users WHERE id=$1 AND NOT disabled FOR SHARE NOWAIT"
            }
        };
        tx.query_opt(sql, &[&id])
            .await?
            .ok_or_else(|| ApiError::not_found("Follow target not found"))?;
    }
    let current = state_in(tx, actor.user_id(), target, id).await?;
    let actual = current["version"]
        .as_i64()
        .ok_or_else(ApiError::unavailable)? as i32;
    if version.is_some_and(|v| v != actual) {
        return Err(ApiError::conflict(
            "Follow membership changed; refresh before submitting",
        ));
    }
    let changed = current["followed"] != follow;
    let (kind, table, column) = target.parts();
    if changed {
        actual
            .checked_add(1)
            .ok_or_else(|| ApiError::conflict("Follow version exhausted"))?;
        if follow {
            if matches!(target, Target::Manga) {
                // New follows use existing native private/notification defaults;
                // a repeated follow never overwrites an existing reading status.
                super::repository::upsert_follow(
                    tx,
                    actor.user_id(),
                    id,
                    "plan_to_read",
                    None,
                    None,
                )
                .await?;
            } else {
                tx.execute(&format!("INSERT INTO {table}(user_id,{column}) VALUES($1,$2) ON CONFLICT(user_id,{column}) DO NOTHING"),&[&actor.user_id(),&id]).await?;
            }
        } else {
            let removed = tx
                .execute(
                    &format!("DELETE FROM {table} WHERE user_id=$1 AND {column}=$2"),
                    &[&actor.user_id(), &id],
                )
                .await?;
            if removed > 0 && matches!(target, Target::Manga) {
                tx.execute("UPDATE platform.catalog_manga_counters SET follows=GREATEST(0,follows-1) WHERE manga_id=$1",&[&id]).await?;
            }
        }
    }
    let mut result = state_in(tx, actor.user_id(), target, id).await?;
    result["scope"] = json!("instance-account");
    result["source"] = json!("persisted-native-account-follows");
    result["accountId"] = json!(account_id);
    result["kind"] = json!(kind);
    result["changed"] = json!(changed);
    result["versionSemantics"] = json!("membership-change-revision");
    Ok(result)
}

