			if (!current || current.id !== staged.id || current.can_cancel !== true) throw resumeError(409);
			await cancelResume(current, owner); owner.assert();
			if (uploadSession?.id !== staged.id) throw resumeError(409);
			for (const file of staged.relationships.files ?? []) if (file.thumbnail?.startsWith("blob:")) { if (!revokeUploadPreviewUrl(file.thumbnail)) URL.revokeObjectURL(file.thumbnail); }
			window.clearTimeout(resumeSaveTimer); uploadSession = undefined; lastSavedUpload = "";
			draft = { language: draft.language }; isOneshot = false; isTemsAccepted = false;
			toast.success("Staged upload cancelled", { description: "The server confirmed cancellation. No chapter publication was cancelled or peer copy removed." });
		} catch (error) { showResumeError(error); }
	});

	const isPending = async () => {
		if (!draft.language) {
			throw Constants.Error.Unknown;
		}

		const res = await owner.request<{ requiresApproval: boolean }>("/upload/check-approval-required", "POST", { language: draft.language });
		if (res?.status === StatusCodes.OK && typeof res.body?.requiresApproval === "boolean") {
			return res.body.requiresApproval;
		} else if (res?.status === StatusCodes.FORBIDDEN) {
			throw Constants.Error.Forbidden;
		} else if (res?.status === StatusCodes.TOO_MANY_REQUESTS) {
			throw Constants.Error.TooManyRequests;
		} else throw Constants.Error.Unknown;
	};
</script>

<Dialog.Root
	bind:open={isShowMessage}
	onOpenChange={async open => {
		if (open) return;

		isShowMessage = false;
		if (isBeginAnotherUploadSession) {
			isBeginAnotherUploadSession = false;
			uploadSession = undefined;
			draft = { language: draft.language };
			isOneshot = false;

			createUploadSession();
		} else {
			if (chapter) await goto(`/chapter/${chapter.id}/1`);
			else await goto(`/title/${manga.id}${Utils.makeSlug(manga.title)}`);
		}
	}}
>
	<Dialog.Content>
		<Dialog.Header>
			<Dialog.Title>{message?.title}</Dialog.Title>
			<Dialog.Description>
				{@html message?.description}
			</Dialog.Description>
		</Dialog.Header>
		<Dialog.Footer>
			{#if signedReceiptPending}
				<Button variant="outline" type="button" disabled={$mutex} onclick={checkSignedUploadReceipt}>Check saved publication receipt</Button>
			{/if}
			<Dialog.Close>
				{#snippet child({ props })}
					<Button class="border-none" variant="outline" type="button" {...props}>Close</Button>
				{/snippet}
			</Dialog.Close>
		</Dialog.Footer>
	</Dialog.Content>
</Dialog.Root>

<section class="mx-auto flex w-full max-w-270 flex-auto flex-col space-y-5">
	<header class="space-y-5">
		<h2 class="text-xl font-medium">Upload Chapter</h2>
	</header>
	<UploadSchedulesPanel {owner} revision={scheduleRevision} />
	<form class="space-y-5" onsubmit={uploadSession ? commitUploadSession : createUploadSession}>
		<div class="space-y-2">
			<Label>Title</Label>
			<ReportMangaCard {manga} />
		</div>

		<Separator />
		<UploadChapterGroups {user} bind:groups enabled={!uploadSession} disabled={$mutex || !!uploadSession} />

		{#if uploadSession}
			<Separator />
			<UploadChapterMetadata
				bind:draft
				bind:isOneshot
				{isVolumeValid}
				{isChapterValid}
				disabled={$mutex || !uploadSession || uploadSession.can_mutate === false}
			/>

			<Separator />
			<UploadChapterPages bind:pages={uploadSession.relationships.files!} disabled={$mutex || !uploadSession} />
			<fieldset class="space-y-2 rounded border p-3" disabled={$mutex || uploadSession.can_mutate === false}>
				<legend>Publication timing</legend>
				<label class="flex gap-2"><input type="checkbox" bind:checked={scheduleEnabled} />Schedule for later</label>
				{#if scheduleEnabled}
					<label for="publish-at-utc">Publishing date and time (UTC)</label>
					<input id="publish-at-utc" type="text" class="block w-full rounded border p-2" bind:value={publishAt} placeholder="YYYY-MM-DDTHH:MM:SS" aria-describedby="publish-at-help" aria-invalid={!scheduleValid} />
					<p id="publish-at-help">Use UTC, not your local time. Pages stay private until publishing starts. You cannot change pages or details after scheduling. A past time publishes immediately.</p>
					{#if !scheduleValid}<p role="status">Enter a real UTC date and time in YYYY-MM-DDTHH:MM:SS format.</p>{/if}
				{:else}<p>Publish when this upload is ready.</p>{/if}
			</fieldset>

			<Separator />
			<div class="space-y-2">
				<div class="flex items-center">
					<Checkbox id="terms" bind:checked={isTemsAccepted} disabled={$mutex || uploadSession.can_mutate === false} />
					<Label class="block cursor-pointer pl-2" for="terms">
						I have read and agree to the
						<a
							class="hover:text-accent-foreground underline"
							href="/terms"
							target="_blank"
							onclick={e => {
								e.stopPropagation();
								e.stopImmediatePropagation();
							}}
						>
							Terms of Service
						</a>
						and
						<a
							class="hover:text-accent-foreground underline"
							href="/guidelines"
							target="_blank"
							onclick={e => {
								e.stopPropagation();
								e.stopImmediatePropagation();
							}}
						>
							Guidelines
						</a>
					</Label>
				</div>
			</div>
		{/if}

		<Separator />
		<div class="bg-background sticky bottom-0 flex flex-wrap justify-end gap-1 py-1">
			{#if uploadSession}
				{#if uploadSession.can_cancel === true && !uploadSession.is_committed}
					<ConfirmDialog title="Cancel staged upload?" description="Discard this private staging session and its files? Prepared publications cannot be cancelled here." confirmText="Cancel staged upload" onConfirm={dialogMutex => dialogMutex.exec(cancelCurrentUpload)} disabled={$mutex}>
						{#snippet child({ props })}<Button class="border-none" variant="outline" type="button" {...props}>Cancel staged upload</Button>{/snippet}
					</ConfirmDialog>
